/// A simple representation of a Hermite E polynomial.
///
/// - `coef` holds the coefficients of the polynomial in ascending order.
/// - `domain` is fixed to [-1.0, 1.0].
/// - `window` is fixed to [-1.0, 1.0].
#[derive(Debug, Clone, PartialEq)]
pub struct HermiteEPoly {
    pub coef: Vec<f32>,
    pub domain: (f32, f32),
    pub window: (f32, f32),
}

/// Constructs a Hermite E polynomial with the given coefficients.
/// 
/// The returned `HermiteEPoly` will:
/// - Preserve the exact coefficients in `coef`.
/// - Have its domain fixed to [-1.0, 1.0].
/// - Have its window fixed to [-1.0, 1.0].
pub fn hermite_e(coef: Vec<f32>) -> HermiteEPoly {
    HermiteEPoly {
        coef,
        domain: (-1.0, 1.0),
        window: (-1.0, 1.0),
    }
}

